#!/usr/bin/env python3
"""Generate the deliberately narrow Fan Home wire contract from canonical OpenAPI.

This does not generate the whole CrowdRelay client: transport/retry/cache remain
hand-written. It pins only the small cross-process DTO surface that must not drift.
"""
from __future__ import annotations
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OPENAPI = ROOT.parent / "crowdrelay" / "openapi" / "openapi.yaml"
OUT = ROOT / "crates" / "virya-signal-contracts" / "src" / "fan_wire.generated.rs"
raw = OPENAPI.read_bytes()
text = raw.decode()
required = [
    "FanHomeSnapshot:", "FanHomeProfile:", "FanHomeEvent:", "FanHomeSynesthesia:",
    "FanHomeReferral:", "FanHomeCounts:", "FanRecommendedAction:", "FanRecommendedActionDetail:",
]
missing = [item for item in required if item not in text]
if missing:
    raise SystemExit(f"missing canonical OpenAPI schemas: {', '.join(missing)}")
digest = hashlib.sha256(raw).hexdigest()
body = f'''// @generated by scripts/generate-crowdrelay-fan-contract.py; do not hand-edit.\n// @crowdrelay-openapi-sha256 {digest}\nuse serde::{{Deserialize, Serialize}};\n\n#[derive(Clone, Debug, Default, Deserialize, Serialize, PartialEq, Eq)]\n#[serde(rename_all = "snake_case")]\npub enum FanRecommendedAction {{\n    ContinueSynesthesia,\n    OpenWallet,\n    OpenLiveEvent,\n    SharePostShowFeedback,\n    GetTicket,\n    FollowNextEvent,\n    ExploreSignal,\n    #[default]\n    #[serde(other)]\n    Unknown,\n}}\n\n#[derive(Clone, Debug, Deserialize, Serialize)]\npub struct FanRecommendedActionDetail {{\n    pub kind: FanRecommendedAction,\n    pub priority: u8,\n    pub target: String,\n    pub expires_at: Option<String>,\n    pub reason: String,\n}}\n\n#[derive(Clone, Debug, Default, Deserialize, Serialize)]\npub struct FanHomeData {{\n    pub schema_version: u32,\n    pub generated_at: String,\n    pub profile: FanHomeProfile,\n    pub next_event: Option<FanHomeEvent>,\n    pub synesthesia: FanHomeSynesthesia,\n    pub referral: FanHomeReferral,\n    pub counts: FanHomeCounts,\n    pub recommended_action: FanRecommendedAction,\n    #[serde(default)]\n    pub recommended: Option<FanRecommendedActionDetail>,\n    #[serde(default)]\n    pub stale: bool,\n}}\n\nimpl FanHomeData {{\n    pub const SCHEMA_VERSION: u32 = 1;\n    pub fn has_supported_schema(&self) -> bool {{ self.schema_version == Self::SCHEMA_VERSION }}\n}}\n\n#[derive(Clone, Debug, Default, Deserialize, Serialize)]\npub struct FanHomeProfile {{\n    pub display_name: Option<String>,\n    pub locale: Option<String>,\n    pub primary_city: Option<String>,\n}}\n\n#[derive(Clone, Debug, Deserialize, Serialize)]\npub struct FanHomeEvent {{\n    pub slug: String,\n    pub title: String,\n    pub venue: Option<String>,\n    pub city: Option<String>,\n    pub starts_at: String,\n    pub doors_at: Option<String>,\n    pub ends_at: Option<String>,\n    pub phase: String,\n    pub ticket_url: Option<String>,\n    pub interested: bool,\n    pub has_pass: bool,\n    pub has_paid_ticket: bool,\n    pub ticket_sale_active: bool,\n}}\n\n#[derive(Clone, Debug, Default, Deserialize, Serialize)]\npub struct FanHomeSynesthesia {{\n    pub started: bool,\n    pub completed: bool,\n    pub rooms_completed: i16,\n    pub client_total_elapsed_ms: Option<i64>,\n    pub best_elapsed_ms: Option<i64>,\n    pub completed_runs: i64,\n    pub leaderboard_published: bool,\n    pub leaderboard_rank: Option<i64>,\n    pub linked_at: Option<String>,\n    pub reward_entered: bool,\n}}\n\n#[derive(Clone, Debug, Default, Deserialize, Serialize)]\npub struct FanHomeReferral {{ pub qualified: i64, pub pending: i64 }}\n\n#[derive(Clone, Debug, Default, Deserialize, Serialize)]\npub struct FanHomeCounts {{\n    pub event_interests: i64,\n    pub active_passes: i64,\n    pub paid_orders: i64,\n    pub area_claims: i64,\n}}\n'''
OUT.write_text(body)
print(f"SIGNAL_FAN_CONTRACT=GENERATED openapi_sha256={digest}")
